"""Pure-Python git metadata detection.

This module reads git's on-disk data structures directly (``HEAD``, loose and
packed refs, and the repository ``config``) instead of shelling out to the
``git`` executable. This keeps the client dependency-free and works in
environments where ``git`` is not installed on ``PATH``.
"""

from __future__ import annotations

import configparser
import logging
import os
from pathlib import Path

log = logging.getLogger(__name__)

_REFS_HEADS_PREFIX = "refs/heads/"
_REFS_TAGS_PREFIX = "refs/tags/"


def _find_git_dir(path: str) -> Path | None:
    """Traverse upward from *path* looking for a ``.git`` entry.

    If ``.git`` is a directory it is returned directly. If it is a file (as
    used by linked worktrees and submodules) the ``gitdir:`` pointer it
    contains is resolved -- either as an absolute path or relative to the
    ``.git`` file's parent directory. Returns ``None`` if no ``.git`` entry is
    found in the directory hierarchy.
    """
    current = Path(path)
    for directory in (current, *current.parents):
        git_path = directory / ".git"
        if git_path.is_dir():
            return git_path
        if git_path.is_file():
            return _resolve_gitdir_pointer(git_path)
    return None


def _resolve_gitdir_pointer(git_file: Path) -> Path | None:
    """Resolve the ``gitdir:`` pointer stored in a ``.git`` file."""
    try:
        content = git_file.read_text()
    except OSError:
        return None
    for line in content.splitlines():
        line = line.strip()
        if line.startswith("gitdir:"):
            pointer = line[len("gitdir:") :].strip()
            pointer_path = Path(pointer)
            if pointer_path.is_absolute():
                return pointer_path
            return Path(os.path.normpath(git_file.parent / pointer_path))
    return None


def _read_head_content(git_dir: Path) -> str | None:
    """Read ``git_dir/HEAD``, stripping trailing whitespace.

    Returns ``None`` if the file does not exist.
    """
    head = git_dir / "HEAD"
    try:
        return head.read_text().rstrip()
    except OSError:
        return None


def _resolve_ref(git_dir: Path, ref: str) -> str | None:
    """Resolve *ref* (e.g. ``refs/heads/main``) to a commit SHA.

    Checks the loose ref file at ``git_dir/ref`` first, then falls back to
    ``git_dir/packed-refs``. Returns ``None`` if the ref cannot be found.
    """
    loose = git_dir / ref
    try:
        return loose.read_text().strip()
    except OSError:
        pass

    packed = git_dir / "packed-refs"
    try:
        lines = packed.read_text().splitlines()
    except OSError:
        return None

    for raw in lines:
        line = raw.strip()
        if not line or line.startswith("#") or line.startswith("^"):
            continue
        sha, _, name = line.partition(" ")
        if name == ref:
            return sha
    return None


def _read_head_sha(git_dir: Path) -> str | None:
    """Return the commit SHA currently pointed to by HEAD.

    Handles both detached HEAD (a raw SHA) and symbolic refs
    (``ref: refs/heads/<branch>``). Returns ``None`` if HEAD is missing.
    """
    content = _read_head_content(git_dir)
    if content is None:
        return None
    if content.startswith("ref:"):
        ref = content[len("ref:") :].strip()
        return _resolve_ref(git_dir, ref)
    return content


def _find_tag_in_packed_refs(git_dir: Path, sha: str) -> str | None:
    """Search ``git_dir/packed-refs`` for a tag pointing at *sha*.

    Lightweight tags store the commit SHA directly on the
    ``<sha> refs/tags/<name>`` line. Annotated tags store the tag object's SHA
    there, followed by a ``^<commit-sha>`` dereference line. Returns the tag
    name (the part after ``refs/tags/``) or ``None`` if no matching tag exists
    or ``packed-refs`` is absent.
    """
    packed = git_dir / "packed-refs"
    try:
        lines = packed.read_text().splitlines()
    except OSError:
        return None

    for i, raw in enumerate(lines):
        line = raw.strip()
        if not line or line.startswith("#") or line.startswith("^"):
            continue
        obj_sha, _, name = line.partition(" ")
        if not name.startswith(_REFS_TAGS_PREFIX):
            continue
        # Lightweight tag: the commit SHA is on the tag line itself.
        if obj_sha == sha:
            return name[len(_REFS_TAGS_PREFIX) :]
        # Annotated tag: the commit SHA is on the following `^<sha>` line.
        if i + 1 < len(lines):
            nxt = lines[i + 1].strip()
            if nxt.startswith("^") and nxt[1:].strip() == sha:
                return name[len(_REFS_TAGS_PREFIX) :]
    return None


def get_git_version(git_dir: Path) -> str | None:
    """Return the current commit SHA, or ``None`` if HEAD is missing."""
    return _read_head_sha(git_dir)


def get_git_branch(git_dir: Path) -> str | None:
    """Return the current branch name.

    Reads the symbolic ref from HEAD and strips the ``refs/heads/`` prefix.
    Returns ``None`` when HEAD is detached (a raw SHA) or does not exist.
    """
    content = _read_head_content(git_dir)
    if content is None or not content.startswith("ref:"):
        return None
    ref = content[len("ref:") :].strip()
    if ref.startswith(_REFS_HEADS_PREFIX):
        return ref[len(_REFS_HEADS_PREFIX) :]
    return ref


def get_git_tag(git_dir: Path) -> str | None:
    """Return the name of a tag pointing at the current commit.

    Searches loose tag files under ``git_dir/refs/tags/`` recursively first,
    then falls back to ``packed-refs``. Returns the tag name relative to
    ``refs/tags/`` or ``None`` if no matching tag is found or HEAD is missing.
    """
    sha = _read_head_sha(git_dir)
    if sha is None:
        return None

    tags_dir = git_dir / "refs" / "tags"
    if tags_dir.is_dir():
        for tag_file in sorted(tags_dir.rglob("*")):
            if not tag_file.is_file():
                continue
            try:
                content = tag_file.read_text().strip()
            except OSError:
                continue
            if content == sha:
                return tag_file.relative_to(tags_dir).as_posix()

    return _find_tag_in_packed_refs(git_dir, sha)


def get_git_repo_url(repo_url: str | None = None, git_dir: Path | None = None) -> str | None:
    """Return the repository URL.

    If *repo_url* is a non-empty string it is returned as-is. Otherwise the
    ``origin`` remote URL is read from ``git_dir/config`` using a raw
    (non-interpolating) config parser so that URLs containing percent signs do
    not raise errors. Returns ``None`` if no URL is available, the config file
    is missing, no ``origin`` remote exists, or no git dir is available.
    """
    if repo_url:
        return repo_url
    if git_dir is None:
        return None

    config_path = git_dir / "config"
    if not config_path.is_file():
        return None

    # RawConfigParser avoids `%`-interpolation, which would otherwise choke on
    # URLs that legitimately contain percent signs (e.g. percent-encoded auth).
    parser = configparser.RawConfigParser()
    try:
        parser.read(config_path)
    except configparser.Error:
        log.debug("Failed to parse git config at `%s`", config_path
